import java.util.*; class Solution { public int strongPasswordChecker(String password) { int n = password.length(); int lower = 1, upper = 1, digit = 1; for (char c : password.toCharArray()) { if (Character.isLowerCase(c)) lower = 0; else if (Character.isUpperCase(c)) upper = 0; else if (Character.isDigit(c)) digit = 0; } int missingType = lower + upper + digit; List<Integer> repeats = new ArrayList<>(); int i = 0; while (i < n) { int j = i; while (j < n && password.charAt(j) == password.charAt(i)) j++; int len = j - i; if (len >= 3) repeats.add(len); i = j; } if (n < 6) { return Math.max(6 - n, missingType); } else if (n <= 20) { int replace = 0; for (int len : repeats) replace += len / 3; return Math.max(replace, missingType); } else { int delete = n - 20; int replace = 0; int[] count = new int[3]; for (int len : repeats) { int rem = len % 3; if (rem == 0) count[0] += len / 3; else if (rem == 1) count[1]++; else count[2] += 2; } int canDelete = delete; for (int k = 0; k < 3; k++) { if (k == 0) { int take = Math.min(canDelete / 3, count[0]); replace += (lenToReplace(k, count[k]) - take); canDelete -= take * 3; } else if (k == 1) { int take = Math.min(canDelete, count[1]); replace += (lenToReplace(k, count[k]) - take / 1); canDelete -= take; } else { int take = Math.min(canDelete, count[2]); replace += (lenToReplace(k, count[k]) - take / 3); canDelete -= take; } } return delete + Math.max(replace, missingType); } } private int lenToReplace(int rem, int count) { return count; } }